{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Melagatran, a structurally similar polar direct thrombin inhibitor with ionizable amidine/guanidine and carboxylate groups, had oral bioavailability lowered to only 0.9% after food intake, directly supporting low F for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Melagatran has an oral bioavailability of only 3–7% in humans, confirming very poor absorption for this class of highly ionized peptidomimetic thrombin inhibitors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Inogatran, a close analogue with a guanidine, cyclohexyl side chain, and glycine/proline-like backbone, showed <5% oral bioavailability in healthy volunteers, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065a, a non-peptidic small molecule with strong basic amidino groups, had human oral bioavailability of only 2–3%, attributed to the amidine groups; this supports low F for the query's benzamidine-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A related amidine-containing compound had absolute bioavailability not high enough for oral use in humans, reinforcing the poor permeability of this chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly ionized, polar peptidomimetic thrombin inhibitor with a benzamidine, carboxylic acid, and multiple H-bond donors, predicting poor membrane permeability. Direct and close analogue experimental evidence—melagatran (3–7%, 0.9% after food), inogatran (<5%), and DX-9065a (2–3%)—consistently shows very low oral bioavailability for this chemotype. The prodrug AZD0837's higher F (22–55%) reflects prodrug masking and does not apply to the active metabolite. Therefore, F <20% is predicted.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "AZD0837 data are for a prodrug and not directly transferable to the active metabolite.",
    "Food-effect and transporter-mediated absorption for the query are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

